INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23965$nota-0056$m23965$, $m23966$Training and Racing with a Power Meter.pdf$m23966$, $m23967$147$m23967$, $m23968$Maximal Power Available (MPA)... reveals in real time how much power a rider can generate at any point during a ride by integrating sophisticated fatigue modeling with a rider's unique three-parameter Fitness Signature, comprised of Peak Power (PP), High Intensity Energy (HIE), and Threshold Power (TP).$m23968$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23969$nota-0056$m23969$, $m23970$Training and Racing with a Power Meter.pdf$m23970$, $m23971$148$m23971$, $m23972$As you fatigue it gets harder and harder to maintain a specific wattage above your Threshold Power... the amount of power you have, your MPA, declines as an effort or interval continues and you fatigue, and it is restored when your effort eases.$m23972$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23973$nota-0056$m23973$, $m23974$nota-0045$m23974$, $m23975$alternativa-a$m23975$, $m23976$modelo concorrente/complementar ao FRC do Power Duration Model dos próprios autores — mesmo objetivo (quantificar reserva de trabalho acima do FTP), abordagem de terceiros (software Xert)$m23976$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23977$nota-0057$m23977$, $m23978$Training and Racing with a Power Meter.pdf$m23978$, $m23979$141$m23979$, $m23980$When you plot power on the Y-axis of the graph and cadence on the X-axis, it becomes easy to see at which cadence you had the highest power outputs and your upper cadence limit to produce high wattage.$m23980$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23981$nota-0057$m23981$, $m23982$Training and Racing with a Power Meter.pdf$m23982$, $m23983$142$m23983$, $m23984$a power balance scatterplot helps to identify which leg a rider favors across the range of his or her wattage output. Some riders will 'save' or 'rest' a leg at lower wattages so that when they need more power for short periods of time, they can use that rested leg.$m23984$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23985$nota-0057$m23985$, $m23986$Training and Racing with a Power Meter.pdf$m23986$, $m23987$143$m23987$, $m23988$at a certain cadence, about 100–105 rpm, as you can see from the plot, he shifts to a harder gear in order to continue increasing his speed.$m23988$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23989$nota-0059$m23989$, $m23990$Training and Racing with a Power Meter.pdf$m23990$, $m23991$154$m23991$, $m23992$To calculate Normalized Power: 1. Start at the beginning of the data and calculate a 30-second rolling average for power. 2. Raise the values obtained in Step 1 to the fourth power. 3. Calculate the average of all the values obtained in Step 2. 4. Find the fourth root of the number obtained in Step 3.$m23992$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23993$nota-0059$m23993$, $m23994$Training and Racing with a Power Meter.pdf$m23994$, $m23995$154$m23995$, $m23996$it's the wattage you would have averaged if you had pedaled smoothly for the entire effort—the power that your body thought it was doing... It estimates the power that you could have maintained for the same physiological cost if your power output had been perfectly constant.$m23996$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23997$nota-0059$m23997$, $m23998$nota-0002$m23998$, $m23999$pre-requisito$m23999$, $m24000$generaliza a limitação de potência média/trabalho total já discutida (o mesmo kJ pode representar cargas fisiológicas muito diferentes)$m24000$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24001$nota-0060$m24001$, $m24002$Training and Racing with a Power Meter.pdf$m24002$, $m24003$155$m24003$, $m24004$Charles Howe coined the term Variability Index... To find the Variability Index, simply take the Normalized Power number and divide it by the average power number. The more variable your ride... the higher the Variability Index.$m24004$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24005$nota-0060$m24005$, $m24006$Training and Racing with a Power Meter.pdf$m24006$, $m24007$156$m24007$, $m24008$TABLE 7.1 Variability Indexes for Common Rides — Steady isopower workout 1.00-1.02; Flat road race 1.00-1.06; Flat time trial 1.00-1.04; Hill-climb time trial 1.00-1.06; Flat criterium 1.06-1.35; Hilly criterium 1.13-1.50; Hilly road race 1.20-1.35; Mountain-bike race 1.13-1.50$m24008$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24009$nota-0060$m24009$, $m24010$nota-0059$m24010$, $m24011$pre-requisito$m24011$, $m24012$VI é calculado a partir do NP definido na nota-0059$m24012$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24013$nota-0061$m24013$, $m24014$Training and Racing with a Power Meter.pdf$m24014$, $m24015$158$m24015$, $m24016$Intensity Factor is simply the ratio of your Normalized Power to your functional threshold power—that is, the fraction of your functional threshold power that you maintained for that workout (i.e., IF = NP/FTP).$m24016$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24017$nota-0061$m24017$, $m24018$Training and Racing with a Power Meter.pdf$m24018$, $m24019$158$m24019$, $m24020$an IF of more than 1.05 for a race that is approximately 1 hour in duration is often a sign that the rider's threshold power is actually greater than that presently entered into the TrainingPeaks WKO Software program.$m24020$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24021$nota-0061$m24021$, $m24022$Training and Racing with a Power Meter.pdf$m24022$, $m24023$159$m24023$, $m24024$he sees that his TSS is 114 and his IF is 1.07, with his normalized watts at 310... Joe adjusts his threshold value to 310, lets the software recalculate his TSS and IF, and sees that the TSS is now 100 and the IF is now 1.0.$m24024$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24025$nota-0061$m24025$, $m24026$nota-0059$m24026$, $m24027$pre-requisito$m24027$, $m24028$IF é calculado a partir do NP definido na nota-0059$m24028$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24029$nota-0061$m24029$, $m24030$nota-0050$m24030$, $m24031$complementa$m24031$, $m24032$outro sinal de que o FTP cadastrado está desatualizado e precisa ser recalculado$m24032$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24033$nota-0062$m24033$, $m24034$Training and Racing with a Power Meter.pdf$m24034$, $m24035$160$m24035$, $m24036$The formula for TSS is TSS = [(s × W × IF) ÷ (FTP × 3,600)] × 100 where s is duration in seconds, W is Normalized Power in watts, IF is Intensity Factor, FTP is functional threshold power, and 3,600 is number of seconds in 1 hour.$m24036$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m24037$nota-0062$m24037$, $m24038$Training and Racing with a Power Meter.pdf$m24038$, $m24039$160$m24039$, $m24040$The Training Stress Score is based on a 1-hour time trial at threshold. An athlete riding for 1 hour at FTP would score 100 TSS points, and the IF from this ride would be 1.0.$m24040$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24041$nota-0062$m24041$, $m24042$nota-0059$m24042$, $m24043$pre-requisito$m24043$, $m24044$TSS usa o NP (nota-0059) na fórmula$m24044$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m24045$nota-0062$m24045$, $m24046$nota-0061$m24046$, $m24047$pre-requisito$m24047$, $m24048$TSS usa o IF (nota-0061) na fórmula$m24048$)
